local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[409802]=b({e[23034],409802,1,4,425,"「はーやーくー！ せっかくお姉ちゃんを説得して、あなたにお化粧してもらえることになったのにー。もたもたしてたら開演時間になっちゃうよ！\nえっ、この前は上手くできなかったから自信がない？\nもー、数をこなして慣れるしかないし、こういう機会には目一杯やらなきゃ！\nそれに、あなたが一生懸命わたしに化粧してる時の顔、すっごく好きだから、もっとたくさん見たいしね♪」",200098,1,"deco/character/huayuqing_0",302002,60,false,false,1,false,false,"1",false,false,"-340,0,1",false,"-340,0,1","-340,0,1",2385,987,390,746,873,2328,2014,746,873,2328,1069,false,false,false,false,false,false,false,false,false,false,false,false,"huayuqing_0"},h)g[409803]=b({e[9044],409803,12,179,426,"「おや～、そこのお客さん？ 怪盗の正体は、絶対にバレちゃいけない秘密なんだ～。\nこうなったらわたしと共犯になるか、今夜の月明かりに消えてもらうしかないね～？\n……なーんてねっ、くすくすっ。\n全部演技だし、そう緊張しないでってば。今日は新作の劇のインスピレーションを得るために、ゲスト出演してるだけなの。\nさて、そろそろ戻るから、わたしの活躍、よ～～く目に焼き付けてね！」",200098,2,"deco/character/huayuqing_LF",0,1,4206,5000,2160,2472,3000,10300,10600,6533,14917,8000,3000,"huayuqing_lf"},h)g[409901]=b({e[46057],409901,false,181,427,false,200099,false,"deco/character/huayubai",302002,60,false,false,false,false,-30,"1",false,"0,-10,1","0,-10,1",false,"0,-10,1","0,-10,1","-140,-10,1","0,50,1","-190,-20,1","-140,-20,1",false,false,"-170,-20,1","-180,-60,1","-180,-60,1",false,false,"-170,-90,1",1989,818,390,1015,721,1985,2605,1015,721,1985,1052,"huayubai"},h)g[409902]=b({e[45057],409902,1,4,428,"「今日は化粧班に欠員が出てしまって、君まで駆り出す事態になってしまったわ。本当にごめんなさい。\n私はもうすぐ出来上がるけど、そうね……腰の帯を締めていただけるかしら。\nあ、そうだ、口紅がまだだったわね。もしよかったら、後でお願いしても良いかしら？」",200099,1,"deco/character/huayubai_0",302002,60,false,false,false,false,false,"1",false,"50,0,1",false,false,false,false,"0,40,1",false,false,false,false,false,false,false,false,false,false,false,1676,994,390,646,464,2654,2510,646,688,2654,"huayubai_0"},h)g[409903]=b({e[9044],409903,12,179,429,"「あなたが付き添いを引き受けてくださったおかげで、このどうしても断りきれなかった立食パーティーも、多少気が楽になりました。\n……とはいえ、今のような二人きりの方が、やはり居心地がいいものですね。\n静かに過ごすこの時間は、お芝居のハッピーエンドよりも……ずっと、真実味がありますから。」",200099,2,"deco/c